#[cfg(test)]
mod tests {
    use std::time::Duration;

    use chrono::Utc;
    use rigorix_engine::capacity_ledger::domain::{
        IdempotencyKey, Lease, Reservation, ReservationId, ReservationState,
        ReservationTransitionError, ResourceId,
    };

    fn reservation() -> Reservation {
        Reservation::new(
            ReservationId::new(),
            ResourceId::new("gpu"),
            3,
            Lease::expiring_in(Utc::now(), Duration::from_secs(60)),
            IdempotencyKey::new("k1"),
        )
    }

    #[test]
    fn test_reservation_is_defined() {
        let r = reservation();
        assert_eq!(r.state, ReservationState::Outstanding);
        assert!(!r.is_terminal());
        assert_eq!(r.amount, 3);
        assert_eq!(r.idempotency_key, IdempotencyKey::new("k1"));
    }

    #[test]
    fn test_reservation_interacts_with_resource() {
        let r = reservation();
        assert_eq!(r.resource, ResourceId::new("gpu"));

        // Committed/Released/Expired are terminal; Ambiguous is the
        // reconciliation state and must stay non-terminal.
        assert!(ReservationState::Committed.is_terminal());
        assert!(ReservationState::Released.is_terminal());
        assert!(ReservationState::Expired.is_terminal());
        assert!(!ReservationState::Ambiguous.is_terminal());

        let now = Utc::now();
        let lease = Lease::expiring_in(now, Duration::from_secs(30));
        assert!(!lease.is_expired_at(now));
        assert!(lease.is_expired_at(now + chrono::Duration::seconds(60)));
    }

    #[test]
    fn test_reservation_has_exactly_one_terminal_transition() {
        // Commit is terminal; a second transition is rejected.
        let committed = reservation().commit().expect("commit");
        assert_eq!(committed.state, ReservationState::Committed);
        let retried = committed.clone().release();
        assert!(matches!(
            retried,
            Err(ReservationTransitionError::AlreadyTerminal { .. })
        ));

        // Release is terminal too.
        let released = reservation().release().expect("release");
        assert_eq!(released.state, ReservationState::Released);

        // Expiry only succeeds once the lease has lapsed (I5).
        let now = Utc::now();
        let live = Reservation::new(
            ReservationId::new(),
            ResourceId::new("gpu"),
            1,
            Lease::expiring_in(now, Duration::from_secs(60)),
            IdempotencyKey::new("k2"),
        );
        assert!(matches!(
            live.clone().expire(now),
            Err(ReservationTransitionError::LeaseNotExpired { .. })
        ));
        let expired = live
            .expire(now + chrono::Duration::seconds(120))
            .expect("expire after lease");
        assert_eq!(expired.state, ReservationState::Expired);
    }

    #[test]
    fn test_lapsed_lease_marks_ambiguous_not_terminal() {
        let now = Utc::now();
        let live = Reservation::new(
            ReservationId::new(),
            ResourceId::new("gpu"),
            1,
            Lease::expiring_in(now, Duration::from_secs(60)),
            IdempotencyKey::new("k3"),
        );
        assert!(matches!(
            live.clone().mark_ambiguous(now),
            Err(ReservationTransitionError::LeaseNotExpired { .. })
        ));

        let ambiguous = live
            .mark_ambiguous(now + chrono::Duration::seconds(120))
            .expect("mark ambiguous after lease");
        assert_eq!(ambiguous.state, ReservationState::Ambiguous);
        assert!(!ambiguous.is_terminal());

        // Reconciliation (late commit) is the terminal transition.
        let reconciled = ambiguous.clone().commit().expect("late commit");
        assert_eq!(reconciled.state, ReservationState::Committed);
        assert!(reconciled.is_terminal());

        // Ambiguous cannot be moved back to a non-terminal state.
        assert!(
            ambiguous
                .clone()
                .transition(ReservationState::Outstanding)
                .is_err()
        );
    }
}
